/**
 * Auto-heals and normalizes raw Mermaid diagram code generated by AI models.
 * Fixes common syntax issues including unquoted labels with special characters,
 * unbalanced subgraphs, missing headers, markdown code fence leaks, and non-standard comments.
 */
export function autoHealMermaid(raw: string): string {
  if (!raw || typeof raw !== 'string') return ''

  let text = raw.trim()
  if (!text) return ''

  // 1. Strip markdown code fences (```mermaid ... ``` or ``` ... ```)
  text = text.replace(/^```(?:mermaid)?\s*\n?/i, '').replace(/\n?```\s*$/i, '')

  // 2. Strip leading 'mermaid' keyword if on its own line
  text = text.replace(/^mermaid\s*\n/i, '')

  // 3. Strip markdown blockquote prefixes (> )
  text = text.replace(/^>\s?/gm, '')

  // 4. Convert non-mermaid single-line comments (// or #) to Mermaid comment %%
  text = text.replace(/^(\s*)(?:\/\/|#)(?!\s*\[)(.*)$/gm, '$1%%$2')

  // 5. Remove trailing semicolons on diagram declarations (e.g. 'graph TD;' -> 'graph TD')
  text = text.replace(
    /^(\s*(?:flowchart|graph|sequenceDiagram|classDiagram|stateDiagram|erDiagram|journey|gantt|pie|gitGraph)[^\n;]*);/gim,
    '$1',
  )

  // 6. Check if diagram declaration exists
  const knownHeaders = [
    'flowchart',
    'graph',
    'sequencediagram',
    'classdiagram',
    'statediagram',
    'erdiagram',
    'journey',
    'gantt',
    'pie',
    'gitgraph',
    'mindmap',
    'quadrantchart',
    'xychart',
    'timeline',
    'block-beta',
    'packet-beta',
    'kanban',
    'architecture-beta',
    'c4context',
  ]
  const lines = text.split('\n')
  const firstNonCommentLine =
    lines
      .map((l) => l.trim())
      .find((l) => l.length > 0 && !l.startsWith('%%')) || ''
  const hasHeader = knownHeaders.some((h) =>
    firstNonCommentLine.toLowerCase().startsWith(h),
  )

  if (!hasHeader) {
    text = `flowchart TD\n${text}`
  }

  // 7. If it's an erDiagram, heal common ERD arrow defects
  if (/^\s*erDiagram\b/i.test(text)) {
    // LLMs often output flowchart-style arrows in erDiagram (e.g. USER --> ORDER : places)
    text = text.replace(
      /([a-zA-Z0-9_-]+)\s*(?:-->|->)\s*([a-zA-Z0-9_-]+)/g,
      '$1 ||--o{ $2',
    )
  }

  // 8. Balance subgraphs and ends
  const subgraphCount = (text.match(/^\s*subgraph\b/gim) || []).length
  const endCount = (text.match(/^\s*end\b/gim) || []).length
  if (subgraphCount > endCount) {
    const missingEnds = subgraphCount - endCount
    text = `${text}\n${Array(missingEnds).fill('end').join('\n')}`
  }

  // 9. Fix node labels in flowcharts and graphs
  // Cylinders: id[(label)] -> id[("label")]
  text = text.replace(
    /([a-zA-Z0-9_-]+)\[\(\s*(?!"|\s*")(.*?)\s*\)\]/g,
    (_, id, label) => {
      const sanitized = label.replace(/"/g, "'")
      return `${id}[("${sanitized}")]`
    },
  )

  // Stadiums: id([label]) -> id(["label"])
  text = text.replace(
    /([a-zA-Z0-9_-]+)\(\[\s*(?!"|\s*")(.*?)\s*\]\)/g,
    (_, id, label) => {
      const sanitized = label.replace(/"/g, "'")
      return `${id}(["${sanitized}"])`
    },
  )

  // Subroutines: id[[label]] -> id[["label"]]
  text = text.replace(
    /([a-zA-Z0-9_-]+)\[\[\s*(?!"|\s*")(.*?)\s*\]\]/g,
    (_, id, label) => {
      const sanitized = label.replace(/"/g, "'")
      return `${id}[["${sanitized}"]]`
    },
  )

  // Decision / Rhombus: id{label} -> id{"label"} if label contains special chars
  text = text.replace(
    /([a-zA-Z0-9_-]+)\{\s*(?!"|\s*")(.*?)\s*\}/g,
    (match, id, label) => {
      if (/[()[\]{}<>&:"/%]/.test(label)) {
        const sanitized = label.replace(/"/g, "'")
        return `${id}{"${sanitized}"}`
      }
      return match
    },
  )

  // Rounded: id(label) -> id("label") if label contains special chars
  text = text.replace(
    /([a-zA-Z0-9_-]+)\(\s*(?!"|\s*")(.*?)\s*\)/g,
    (match, id, label) => {
      if (/[()[\]{}<>&:"/%]/.test(label)) {
        const sanitized = label.replace(/"/g, "'")
        return `${id}("${sanitized}")`
      }
      return match
    },
  )

  // Standard square boxes: id[label] -> id["label"] if label contains special chars
  // Negative lookahead (?![([]) ensures cylinders id[(...)] and subroutines id[[...]] are not re-matched
  text = text.replace(
    /([a-zA-Z0-9_-]+)\[(?![([])\s*(?!"|\s*")(.*?)(?=\]\s*(?:-->|---|-.->|==>|~~~|\n|;|$))\]/g,
    (match, id, label) => {
      if (/[()[\]{}<>&:"/%]/.test(label)) {
        const sanitized = label.replace(/"/g, "'")
        return `${id}["${sanitized}"]`
      }
      return match
    },
  )

  // Edge labels: -->|label| -> -->|"label"|
  text = text.replace(
    /(-->|---|-.->|==>|\.\.->)\s*\|(?!"|\s*")(.*?)\|/g,
    (match, arrow, label) => {
      if (/[()[\]{}<>&:"/%]/.test(label)) {
        const sanitized = label.replace(/"/g, "'")
        return `${arrow}|"${sanitized}"|`
      }
      return match
    },
  )

  return text
}
